// Scratch exact native lifted22 component values/gradients, no evolution.
#include "projected_base.hpp"
int main(int argc,char**argv){Kokkos::ScopeGuard guard(argc,argv);try{Audit a(20,2.1967074064860954,1e-4);size_t N=a.cells.size(),dim=20*N;std::vector<double>v(dim),out(N*22*4);std::cout<<"{\"points\":"<<N<<",\"dimension\":"<<dim<<"}\n"<<std::flush;while(std::cin.read(reinterpret_cast<char*>(v.data()),dim*8)){a.LinearFill(v.data());auto dev=hyp::BindCartesianFields(a.delta);const auto&grid=a.patch.grid;Real idx[3]={1/grid.h[0],1/grid.h[1],1/grid.h[2]};for(size_t p=0;p<N;++p){const auto&c=a.cells[p];auto d=hyp::LoadMeshJet<3>(dev,idx,0,c.k,c.j,c.i);for(int f=0;f<22;++f)for(int t=0;t<4;++t)out[(p*22+f)*4+t]=Get(d,f,t);}std::cout.write(reinterpret_cast<char*>(out.data()),out.size()*8);std::cout.flush();}}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
